//! Repository for Warehouse entities
//!
//! Originally generated by metaphor-schema; now **user-owned** — this exact path is declared under
//! `user_owned` in `metaphor.codegen.yaml`, so the generator skips it wholesale. The custom methods
//! below hold the hand-written Warehouse registration SQL
//! (4-layer rule: services orchestrate, repositories hold the SQL).
//!
//! Thin newtype over `backbone_orm::GenericCrudRepository<Warehouse, backbone_orm::SoftDelete>`.
//! All standard CRUD methods are available via `Deref`.

use anyhow::Result;
use sqlx::PgPool;
use uuid::Uuid;

use backbone_orm::company_scope;

use crate::domain::entity::Warehouse;

/// Table name for Warehouse entities
pub const TABLE_NAME: &str = "inventory.warehouses";

/// Repository for Warehouse entities.
///
/// All standard CRUD, soft-delete, pagination, and bulk methods are
/// provided automatically via `Deref` to `backbone_orm::GenericCrudRepository`.
pub struct WarehouseRepository(
    backbone_orm::GenericCrudRepository<Warehouse, backbone_orm::SoftDelete>,
);

impl std::ops::Deref for WarehouseRepository {
    type Target = backbone_orm::GenericCrudRepository<Warehouse, backbone_orm::SoftDelete>;
    fn deref(&self) -> &Self::Target { &self.0 }
}

impl WarehouseRepository {
    /// Create a new repository instance.
    pub fn new(pool: PgPool) -> Self {
        Self(backbone_orm::GenericCrudRepository::new(pool, TABLE_NAME))
    }
}

/// The exact row a warehouse registration writes.
///
/// Mirrors the raw column shape rather than the `Warehouse` entity: `warehouse_type` is cast at the
/// DB (`$5::warehouse_type`) so a bad value fails as a DB error, not a deserialize panic.
pub struct NewWarehouseRow<'a> {
    pub id: Uuid,
    pub company_id: Uuid,
    pub code: &'a str,
    pub name: &'a str,
    pub warehouse_type: &'a str,
    pub parent_warehouse_id: Option<Uuid>,
    pub is_group: bool,
}

/// Hand-written Warehouse SQL. Lives here per the module's 4-layer rule.
impl WarehouseRepository {
    /// Register a warehouse.
    ///
    /// A write outside any transaction: takes the pool and runs `execute_scoped` so the RLS fence
    /// (ADR-0008) applies. The caller wraps this in `with_company_scope(Some(company))` — the
    /// company is on the DTO, and that scope satisfies the INSERT's WITH CHECK fence.
    ///
    /// Returns the raw `sqlx::Error` deliberately: the caller inspects it for a unique violation to
    /// turn a duplicate warehouse code into a domain error.
    pub async fn insert_warehouse(
        &self,
        pool: &PgPool,
        w: &NewWarehouseRow<'_>,
    ) -> Result<(), sqlx::Error> {
        company_scope::execute_scoped(
            pool,
            sqlx::query(
                r#"INSERT INTO inventory.warehouses
                    (id, company_id, code, name, warehouse_type, parent_warehouse_id, is_group)
                   VALUES ($1,$2,$3,$4,$5::warehouse_type,$6,$7)"#,
            )
            .bind(w.id).bind(w.company_id).bind(w.code).bind(w.name).bind(w.warehouse_type)
            .bind(w.parent_warehouse_id).bind(w.is_group),
        )
        .await?;
        Ok(())
    }
}

backbone_core::impl_crud_repository!(WarehouseRepository, Warehouse, soft_delete);
